-- ==============================================================================
-- OPERLY — 60-DAY REVENUE ANALYTICS SEED VALIDATION SQL SUITE
-- ==============================================================================
-- Purpose: Read-only verification of the analytics dataset generated by
--          backend/src/prisma/analytics-seed.ts.
-- Rules:   All queries are strictly READ-ONLY (SELECT only).
--          All revenue calculations use CTEs/subqueries to prevent join fan-out.
--          Zero orphan queries use NOT EXISTS for optimal PostgreSQL performance.
--          Refund validation uses payment-level CTE aggregation to support
--          multiple refund records per payment.
-- Reference Date Range: 2026-09-26 through 2026-11-24 (inclusive)
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. TOTAL GENERATED ENTITY COUNTS BY CATEGORY (Target: 160 S, 160 O, 156 B, 150 P, 5 R)
-- ------------------------------------------------------------------------------
SELECT
    'Dining Sessions' AS entity,
    COUNT(*) AS total_count,
    COUNT(CASE WHEN session_code LIKE 'SESS-ANL-%' THEN 1 END) AS analytics_count
FROM dining_sessions
UNION ALL
SELECT
    'Orders',
    COUNT(*),
    COUNT(CASE WHEN order_code LIKE 'ORD-ANL-%' THEN 1 END)
FROM orders
UNION ALL
SELECT
    'Bills',
    COUNT(*),
    COUNT(CASE WHEN bill_code LIKE 'BILL-ANL-%' THEN 1 END)
FROM bills
UNION ALL
SELECT
    'Payments',
    COUNT(*),
    COUNT(CASE WHEN transaction_code LIKE 'TXN-ANL-%' THEN 1 END)
FROM payments
UNION ALL
SELECT
    'Refunds',
    COUNT(*),
    COUNT(CASE WHEN r.reason LIKE 'REF-ANL-%' THEN 1 END)
FROM refunds r;

-- ------------------------------------------------------------------------------
-- 2. COMPLETED ORDERS SUMMARY
-- ------------------------------------------------------------------------------
SELECT
    o.status,
    COUNT(o.id) AS order_count,
    SUM(o.total_amount) AS sum_total_amount,
    MIN(o.created_at) AS earliest_order,
    MAX(o.created_at) AS latest_order
FROM orders o
WHERE o.order_code LIKE 'ORD-ANL-%'
GROUP BY o.status
ORDER BY o.status;

-- ------------------------------------------------------------------------------
-- 3. BILLS STATUS BREAKDOWN (PAID, PARTIALLY_PAID, VOIDED, UNPAID)
-- ------------------------------------------------------------------------------
SELECT
    b.status AS bill_status,
    COUNT(b.id) AS bill_count,
    SUM(b.subtotal_amount) AS total_gross_sales,
    SUM(b.discount_amount) AS total_discounts,
    SUM(b.final_amount) AS total_invoiced_net
FROM bills b
WHERE b.bill_code LIKE 'BILL-ANL-%'
GROUP BY b.status
ORDER BY bill_count DESC;

-- ------------------------------------------------------------------------------
-- 4. PAYMENT METHOD DISTRIBUTION & VOLUMES (Target: 150 total payments)
-- ------------------------------------------------------------------------------
SELECT
    p.payment_method,
    p.status AS payment_status,
    COUNT(p.id) AS transaction_count,
    SUM(p.amount_paid) AS gross_paid,
    SUM(p.change_amount) AS total_change_returned,
    SUM(p.amount_paid - p.change_amount) AS net_collected_amount,
    ROUND(COUNT(p.id) * 100.0 / SUM(COUNT(p.id)) OVER(), 2) AS txn_share_pct
FROM payments p
WHERE p.transaction_code LIKE 'TXN-ANL-%'
GROUP BY p.payment_method, p.status
ORDER BY p.payment_method, p.status;

-- ------------------------------------------------------------------------------
-- 5. PARTIAL AND FULL REFUNDS AUDIT (Target: 2 Full, 3 Partial, 5 Total)
-- ------------------------------------------------------------------------------
SELECT
    CASE
        WHEN p.status = 'REFUNDED' THEN 'FULL_REFUND'
        WHEN p.status = 'SUCCESS' THEN 'PARTIAL_REFUND'
        ELSE p.status::text
    END AS refund_type,
    r.id AS refund_id,
    p.transaction_code,
    b.bill_code,
    (p.amount_paid - p.change_amount) AS original_payment_net,
    r.amount AS refund_amount,
    p.status AS final_payment_status,
    b.status AS final_bill_status,
    r.reason,
    r.created_at AS refund_timestamp
FROM refunds r
INNER JOIN payments p ON r.payment_id = p.id
INNER JOIN bills b ON p.bill_id = b.id
WHERE p.transaction_code LIKE 'TXN-ANL-%'
ORDER BY r.created_at ASC;

-- ------------------------------------------------------------------------------
-- 6. DAILY REVENUE AGGREGATION (CTE Anti-Fan-Out Architecture)
-- ------------------------------------------------------------------------------
WITH payment_agg AS (
    SELECT
        p.bill_id,
        SUM(p.amount_paid - p.change_amount) AS total_collected
    FROM payments p
    WHERE p.status IN ('SUCCESS', 'REFUNDED')
    GROUP BY p.bill_id
),
refund_agg AS (
    SELECT
        p.bill_id,
        SUM(r.amount) AS total_refunded
    FROM refunds r
    INNER JOIN payments p ON r.payment_id = p.id
    GROUP BY p.bill_id
)
SELECT
    DATE(b.created_at) AS calendar_date,
    COUNT(b.id) AS total_bills,
    SUM(b.subtotal_amount) AS gross_sales,
    SUM(b.discount_amount) AS discounts,
    SUM(b.final_amount) AS invoiced_net_sales,
    COALESCE(SUM(pa.total_collected), 0) AS amount_collected,
    COALESCE(SUM(ra.total_refunded), 0) AS refund_amount,
    (COALESCE(SUM(pa.total_collected), 0) - COALESCE(SUM(ra.total_refunded), 0)) AS net_cash_retained
FROM bills b
LEFT JOIN payment_agg pa ON b.id = pa.bill_id
LEFT JOIN refund_agg ra ON b.id = ra.bill_id
WHERE b.bill_code LIKE 'BILL-ANL-%' AND b.status IN ('PAID', 'PARTIALLY_PAID')
GROUP BY DATE(b.created_at)
ORDER BY calendar_date DESC;

-- ------------------------------------------------------------------------------
-- 7. WEEKLY REVENUE AGGREGATION (ISO Monday Start)
-- ------------------------------------------------------------------------------
WITH payment_agg AS (
    SELECT
        p.bill_id,
        SUM(p.amount_paid - p.change_amount) AS total_collected
    FROM payments p
    WHERE p.status IN ('SUCCESS', 'REFUNDED')
    GROUP BY p.bill_id
),
refund_agg AS (
    SELECT
        p.bill_id,
        SUM(r.amount) AS total_refunded
    FROM refunds r
    INNER JOIN payments p ON r.payment_id = p.id
    GROUP BY p.bill_id
)
SELECT
    DATE_TRUNC('week', b.created_at) AS iso_week_start,
    COUNT(b.id) AS total_bills,
    SUM(b.subtotal_amount) AS gross_sales,
    SUM(b.discount_amount) AS total_discounts,
    SUM(b.final_amount) AS invoiced_sales,
    (COALESCE(SUM(pa.total_collected), 0) - COALESCE(SUM(ra.total_refunded), 0)) AS weekly_net_collected
FROM bills b
LEFT JOIN payment_agg pa ON b.id = pa.bill_id
LEFT JOIN refund_agg ra ON b.id = ra.bill_id
WHERE b.bill_code LIKE 'BILL-ANL-%' AND b.status IN ('PAID', 'PARTIALLY_PAID')
GROUP BY DATE_TRUNC('week', b.created_at)
ORDER BY iso_week_start DESC;

-- ------------------------------------------------------------------------------
-- 8. MONTHLY REVENUE SUMMARY
-- ------------------------------------------------------------------------------
WITH payment_agg AS (
    SELECT
        p.bill_id,
        SUM(p.amount_paid - p.change_amount) AS total_collected
    FROM payments p
    WHERE p.status IN ('SUCCESS', 'REFUNDED')
    GROUP BY p.bill_id
),
refund_agg AS (
    SELECT
        p.bill_id,
        SUM(r.amount) AS total_refunded
    FROM refunds r
    INNER JOIN payments p ON r.payment_id = p.id
    GROUP BY p.bill_id
)
SELECT
    TO_CHAR(b.created_at, 'YYYY-MM') AS month_key,
    COUNT(b.id) AS settled_bills,
    SUM(b.subtotal_amount) AS gross_sales,
    SUM(b.discount_amount) AS discounts,
    SUM(b.final_amount) AS invoiced_net,
    COALESCE(SUM(pa.total_collected), 0) AS total_collected,
    COALESCE(SUM(ra.total_refunded), 0) AS total_refunded,
    (COALESCE(SUM(pa.total_collected), 0) - COALESCE(SUM(ra.total_refunded), 0)) AS monthly_net_cash
FROM bills b
LEFT JOIN payment_agg pa ON b.id = pa.bill_id
LEFT JOIN refund_agg ra ON b.id = ra.bill_id
WHERE b.bill_code LIKE 'BILL-ANL-%' AND b.status IN ('PAID', 'PARTIALLY_PAID')
GROUP BY TO_CHAR(b.created_at, 'YYYY-MM')
ORDER BY month_key DESC;

-- ------------------------------------------------------------------------------
-- 9. TOP-SELLING DISHES BY VOLUME AND REVENUE
-- ------------------------------------------------------------------------------
SELECT
    m.name AS dish_name,
    c.name AS category_name,
    m.price AS unit_price,
    SUM(oi.quantity) AS total_units_sold,
    SUM(oi.quantity * oi.unit_price) AS total_sales_volume
FROM order_items oi
INNER JOIN menu_items m ON oi.menu_item_id = m.id
INNER JOIN categories c ON m.category_id = c.id
INNER JOIN orders o ON oi.order_id = o.id
WHERE o.order_code LIKE 'ORD-ANL-%' AND o.status = 'COMPLETED' AND oi.item_status = 'SERVED'
GROUP BY m.id, m.name, c.name, m.price
ORDER BY total_units_sold DESC;

-- ------------------------------------------------------------------------------
-- 10. CANCELLED ORDERS AUDIT (Target: exactly 4 cancelled orders)
-- ------------------------------------------------------------------------------
SELECT
    o.order_code,
    s.session_code,
    o.status AS order_status,
    s.status AS session_status,
    o.total_amount,
    o.created_at
FROM orders o
INNER JOIN dining_sessions s ON o.session_id = s.id
WHERE o.order_code LIKE 'ORD-ANL-%' AND o.status = 'CANCELLED'
ORDER BY o.created_at ASC;

-- ------------------------------------------------------------------------------
-- 11. REJECTED ORDER ITEMS AUDIT (Target: 6 rejected items)
-- ------------------------------------------------------------------------------
SELECT
    oi.id AS order_item_id,
    o.order_code,
    m.name AS dish_name,
    oi.quantity,
    oi.unit_price,
    oi.item_status,
    oi.rejection_reason,
    oi.created_at
FROM order_items oi
INNER JOIN menu_items m ON oi.menu_item_id = m.id
INNER JOIN orders o ON oi.order_id = o.id
WHERE o.order_code LIKE 'ORD-ANL-%' AND oi.item_status = 'REJECTED'
ORDER BY oi.created_at ASC;

-- ------------------------------------------------------------------------------
-- 12. REFERENTIAL INTEGRITY & ZERO ORPHAN CHECK (Using NOT EXISTS)
-- ------------------------------------------------------------------------------
SELECT 'orphaned_order_items' AS check_type, COUNT(*) AS violations
FROM order_items oi
WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.id = oi.order_id)
UNION ALL
SELECT 'orphaned_orders', COUNT(*)
FROM orders o
WHERE NOT EXISTS (SELECT 1 FROM dining_sessions s WHERE s.id = o.session_id)
UNION ALL
SELECT 'orphaned_bills', COUNT(*)
FROM bills b
WHERE NOT EXISTS (SELECT 1 FROM dining_sessions s WHERE s.id = b.session_id)
UNION ALL
SELECT 'orphaned_payments', COUNT(*)
FROM payments p
WHERE NOT EXISTS (SELECT 1 FROM bills b WHERE b.id = p.bill_id)
UNION ALL
SELECT 'orphaned_refunds', COUNT(*)
FROM refunds r
WHERE NOT EXISTS (SELECT 1 FROM payments p WHERE p.id = r.payment_id);

-- ------------------------------------------------------------------------------
-- 13. DATASET PARTITION & ISOLATION CHECK
-- ------------------------------------------------------------------------------
SELECT
    CASE
        WHEN session_code LIKE 'SESS-ANL-%' THEN 'Analytics 60-Day Dataset'
        WHEN session_code LIKE 'SESS-2026%' THEN 'Original Seed Dataset'
        ELSE 'Runtime POS Dataset'
    END AS partition_name,
    COUNT(DISTINCT s.id) AS session_count,
    COUNT(DISTINCT o.id) AS order_count,
    COUNT(DISTINCT b.id) AS bill_count,
    MIN(s.start_time) AS earliest_session,
    MAX(s.start_time) AS latest_session
FROM dining_sessions s
LEFT JOIN orders o ON s.id = o.session_id
LEFT JOIN bills b ON s.id = b.session_id
GROUP BY 1;

-- ------------------------------------------------------------------------------
-- 14. IDEMPOTENCY VERIFICATION COUNTS
-- ------------------------------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM dining_sessions WHERE session_code LIKE 'SESS-ANL-%') AS sessions_count,
    (SELECT COUNT(*) FROM orders WHERE order_code LIKE 'ORD-ANL-%') AS orders_count,
    (SELECT COUNT(*) FROM bills WHERE bill_code LIKE 'BILL-ANL-%') AS bills_count,
    (SELECT COUNT(*) FROM payments WHERE transaction_code LIKE 'TXN-ANL-%') AS payments_count,
    (SELECT COUNT(*) FROM refunds WHERE reason LIKE 'REF-ANL-%') AS refunds_count;

-- ------------------------------------------------------------------------------
-- 15. STRICT REFUND & PAYMENT INTEGRITY AUDIT (Zero Discrepancy Expected)
-- ------------------------------------------------------------------------------

-- Refund Aggregation Scope (Checks 15.1–15.4):
-- All refund checks aggregate ALL refund records attached to an analytics payment
-- (i.e., joined via payment_id to payments WHERE transaction_code LIKE 'TXN-ANL-%').
-- This validates actual payment integrity end-to-end: if any refund record — regardless
-- of whether it carries a REF-ANL- reason marker — is attached to an analytics payment,
-- it counts toward the cumulative total. This matches the runtime BillingService behavior
-- where createRefund() enforces a cap against all existing refunds for a payment.
-- The only row-level filter on the reason column is in Check 15.1, which validates that
-- no analytics-generated refund (REF-ANL-*) has a non-positive amount.

-- Check 15.1: Non-positive or zero refund amounts (Row-Level, scoped to seed-generated refunds)
-- Scope: Only refunds whose reason starts with REF-ANL- (i.e., created by this seed script).
-- Purpose: Verifies the seed never created a zero or negative refund record.
SELECT 'non_positive_refunds' AS audit_rule, COUNT(*) AS violations
FROM refunds
WHERE reason LIKE 'REF-ANL-%' AND amount <= 0;

-- Check 15.2: Full refunds total mismatch (Payment-Level CTE Aggregation)
-- Scope: ALL refunds attached to analytics payments (via payment_id join).
-- For any analytics payment marked REFUNDED, SUM(all refund amounts) must exactly equal net_paid.
WITH refund_agg AS (
    SELECT
        payment_id,
        SUM(amount) AS total_refunded,
        COUNT(id) AS refund_count
    FROM refunds
    GROUP BY payment_id
)
SELECT
    'full_refund_total_mismatch' AS audit_rule,
    COUNT(*) AS violations
FROM payments p
LEFT JOIN refund_agg ra ON p.id = ra.payment_id
WHERE p.transaction_code LIKE 'TXN-ANL-%'
  AND p.status = 'REFUNDED'
  AND COALESCE(ra.total_refunded, 0) != (p.amount_paid - p.change_amount);

-- Check 15.3: Partial refund validation (Payment-Level CTE Aggregation)
-- Scope: ALL refunds attached to analytics payments (via payment_id join).
-- For any analytics payment marked SUCCESS that has at least one attached refund record,
-- total_refunded must be > 0 AND strictly < net_paid.
-- Analytics payments without any refund records are excluded (INNER JOIN) so they
-- are not incorrectly flagged as violations.
WITH refund_agg AS (
    SELECT
        payment_id,
        SUM(amount) AS total_refunded,
        COUNT(id) AS refund_count
    FROM refunds
    GROUP BY payment_id
)
SELECT
    'partial_refund_invalid' AS audit_rule,
    COUNT(*) AS violations
FROM payments p
INNER JOIN refund_agg ra ON p.id = ra.payment_id
WHERE p.transaction_code LIKE 'TXN-ANL-%'
  AND p.status = 'SUCCESS'
  AND (ra.total_refunded <= 0 OR ra.total_refunded >= (p.amount_paid - p.change_amount));

-- Check 15.4: Over-refund audit (Cumulative refunds exceeding net paid across all payments)
-- Scope: ALL refunds attached to analytics payments (via payment_id join).
-- Reports every analytics payment where SUM(all refunds) > net_paid.
WITH refund_agg AS (
    SELECT
        payment_id,
        SUM(amount) AS total_refunded,
        COUNT(id) AS refund_count
    FROM refunds
    GROUP BY payment_id
)
SELECT
    p.id AS payment_id,
    p.transaction_code,
    (p.amount_paid - p.change_amount) AS net_paid,
    COALESCE(ra.total_refunded, 0) AS total_refunded,
    COALESCE(ra.refund_count, 0) AS refund_count
FROM payments p
INNER JOIN refund_agg ra ON p.id = ra.payment_id
WHERE p.transaction_code LIKE 'TXN-ANL-%'
  AND ra.total_refunded > (p.amount_paid - p.change_amount);

-- Check 15.5: Bill-Level Payment Completeness & Reconciliation
-- Dataset Invariant: Every settled analytics bill (PAID or PARTIALLY_PAID) must have
--   exactly 1 analytics payment record (transaction_code LIKE 'TXN-ANL-%'), and the
--   SUM of net paid amounts must equal the bill's final_amount.
-- Note: In the live Operly application, bills support multiple split payments.
--   This check is scoped to validate the analytics seed dataset's design decision only.
-- Uses LEFT JOIN so bills with zero analytics payments are included in violations (not silently omitted).
WITH bill_payment_agg AS (
    SELECT
        b.id AS bill_id,
        b.bill_code,
        b.final_amount,
        COUNT(p.id) AS payment_count,
        COALESCE(SUM(p.amount_paid - p.change_amount), 0) AS total_net_paid
    FROM bills b
    LEFT JOIN payments p
        ON p.bill_id = b.id
        AND p.transaction_code LIKE 'TXN-ANL-%'
    WHERE b.bill_code LIKE 'BILL-ANL-%'
      AND b.status IN ('PAID', 'PARTIALLY_PAID')
    GROUP BY b.id, b.bill_code, b.final_amount
)
SELECT
    'analytics_bill_payment_mismatch' AS audit_rule,
    COUNT(*) AS violations,
    COUNT(CASE WHEN payment_count = 0 THEN 1 END) AS bills_with_no_payment,
    COUNT(CASE WHEN payment_count > 1  THEN 1 END) AS bills_with_multiple_payments,
    COUNT(CASE WHEN payment_count = 1 AND total_net_paid != final_amount THEN 1 END) AS bills_with_wrong_amount
FROM bill_payment_agg
WHERE payment_count != 1
   OR total_net_paid != final_amount;

-- ------------------------------------------------------------------------------
-- 16. CONTINUOUS 60-DAY CALENDAR DATE-SERIES (Including Zero-Activity Days)
-- ------------------------------------------------------------------------------
WITH calendar AS (
    SELECT generate_series(
        '2026-09-26'::date,
        '2026-11-24'::date,
        '1 day'::interval
    )::date AS calendar_date
),
daily_revenue AS (
    WITH payment_agg AS (
        SELECT
            p.bill_id,
            SUM(p.amount_paid - p.change_amount) AS total_collected
        FROM payments p
        WHERE p.status IN ('SUCCESS', 'REFUNDED')
        GROUP BY p.bill_id
    ),
    refund_agg AS (
        SELECT
            p.bill_id,
            SUM(r.amount) AS total_refunded
        FROM refunds r
        INNER JOIN payments p ON r.payment_id = p.id
        GROUP BY p.bill_id
    )
    SELECT
        DATE(b.created_at) AS bill_date,
        COUNT(b.id) AS total_bills,
        SUM(b.subtotal_amount) AS gross_sales,
        SUM(b.discount_amount) AS discounts,
        SUM(b.final_amount) AS invoiced_net_sales,
        COALESCE(SUM(pa.total_collected), 0) AS amount_collected,
        COALESCE(SUM(ra.total_refunded), 0) AS refund_amount,
        (COALESCE(SUM(pa.total_collected), 0) - COALESCE(SUM(ra.total_refunded), 0)) AS net_cash_retained
    FROM bills b
    LEFT JOIN payment_agg pa ON b.id = pa.bill_id
    LEFT JOIN refund_agg ra ON b.id = ra.bill_id
    WHERE b.bill_code LIKE 'BILL-ANL-%' AND b.status IN ('PAID', 'PARTIALLY_PAID')
    GROUP BY DATE(b.created_at)
)
SELECT
    c.calendar_date,
    COALESCE(dr.total_bills, 0) AS total_bills,
    COALESCE(dr.gross_sales, 0) AS gross_sales,
    COALESCE(dr.discounts, 0) AS discounts,
    COALESCE(dr.invoiced_net_sales, 0) AS invoiced_net_sales,
    COALESCE(dr.amount_collected, 0) AS amount_collected,
    COALESCE(dr.refund_amount, 0) AS refund_amount,
    COALESCE(dr.net_cash_retained, 0) AS net_cash_retained
FROM calendar c
LEFT JOIN daily_revenue dr ON c.calendar_date = dr.bill_date
ORDER BY c.calendar_date ASC;
